from pathlib import Path
import zipfile,hashlib,json
ROOT=Path(__file__).resolve().parents[1]
DIST=ROOT/'dist'
files=[]
for folder in ['app','scripts','tests','shared','integrations/focusflow']:
    for f in (ROOT/folder).rglob('*'):
        if f.is_file() and '__pycache__' not in f.parts and '.gradle' not in f.parts and f.suffix.lower() not in {'.jks','.pem','.key','.p12'} and f.name not in {'upgrade_main_v2.py','finish_v2.py','edit_source.py','design_migration.py'}:files.append(f)
for name in ['Install-Folio-FocusFlow.cmd','Start-Shared-Pen.cmd','dist/FocusFlow.apk','dist/FocusFlow.apk.sha256','dist/shared-pen-tests.txt','dist/release-checks-1.13.3.json','dist/eraser-overlap-tests.txt','dist/eraser-overlap-benchmark.txt','dist/eraser-performance.md','dist/compat-native-build-checks.json','dist/stylus-compatibility-tests.txt','research/device-compatibility.md','dist/release-checks-1.13.2.json','dist/notebook-name-tests.txt','dist/release-checks-1.13.1.json','dist/provider-health-tests.txt','dist/auto-adb-tests.txt','dist/shared-host-tests.txt','dist/shared-artifact-checks.json','dist/release-checks-1.13.0.json','dist/release-checks-1.12.1.json','README.md','build.gradle','settings.gradle','.gitignore','Install-Folio.cmd','Start-Folio-Pen.cmd','dist/Folio.apk','dist/Folio.apk.sha256','dist/recovery-checks.txt','dist/native-radial-order-tests.txt','dist/Folio-radial-order.png','dist/release-checks-1.12.0.json','dist/native-functional-tests.txt','dist/command-timing-tests.txt','dist/performance-comparison.md','dist/performance-before.json','dist/performance-after.json','dist/native-performance-before.txt','dist/native-performance-after.txt','dist/installed-release-1.12.0.json','dist/release-checks-1.11.0.json','dist/Folio-three-presets.png','dist/device-tests.txt','dist/release-checks.json','dist/geometry-tests.txt','dist/popover-tests.txt','dist/system-chrome-tests.txt','dist/live-ink-tests.txt','dist/color-tests.txt','dist/squeeze-tests.txt','dist/canvas-upgrade-tests.txt','dist/guide-tests.txt','dist/canvas-default-tests.txt','dist/texture-asset-tests.txt','dist/material-asset-tests.txt','dist/content-model-tests.txt','dist/native-enhancement-tests.txt','dist/reference-audit.md','dist/reference-audit.json','dist/Folio-workshop.png','dist/Folio-materials-and-tools.png','dist/Folio-ocr-test.png','dist/native-texture-tests.txt','dist/native-general-tests-1.10.0.txt','dist/Folio-freenotes-textures.png','dist/document-upgrade-tests.txt','dist/Folio-canvas-upgrade.png','dist/Folio-color-palette.png','dist/laser-tests.txt','dist/shape-tests.txt','dist/extended-shape-tests.txt','dist/quadrilateral-tests.txt','dist/pen-feedback-tests.txt','dist/Folio-shape-recognition.png','dist/palette-tests.txt','dist/canvas-tests.txt','dist/marker-tests.txt','dist/Folio-flat-marker.png','dist/Folio-shape-assist.png','dist/Folio-laser-motion.gif','dist/Folio-popover-motion.gif','dist/Folio-ink-geometry.png','dist/device-tests-1.2.txt','dist/release-checks-1.2.json']:
    files.append(ROOT/name)
with zipfile.ZipFile(DIST/'Folio-source.zip','w',zipfile.ZIP_DEFLATED) as z:
    for f in files:z.write(f,f.relative_to(ROOT).as_posix())
print('Source archive:',DIST/'Folio-source.zip')
print('APK SHA-256:',hashlib.sha256((DIST/'Folio.apk').read_bytes()).hexdigest())
